 /** 
@RestController 
public class RestController 
{ 
  private final EssentialService essentialService;
  public RestController(EssentialService essentialService) {
    this.essentialService = essentialService;
  }

  @GetMapping("/geolocation") 
  public Map<String, Object> getGeolocation( 
      @RequestParam String query, 
      @RequestParam int radius) {
    Map<String, Object> result = new HashMap<>();
    try {
      final String x = essentialService.find(query, radius);
      result.put("location", x);
    } catch (Exception e) {
      result.put("location", e.getMessage());
    }
    return result;
  } 

  @PostMapping("/add")
  public String addLocation(@RequestBody Map<String, Object> data) {
    try {
      return essentialService.addLocation(data);
    } catch (Exception e) {
      return e.getMessage();
    }
  }

  @PostMapping("/remove")
  public String removeLocation(@RequestBody Map<String, Object> data) {
    try {
      return essentialService.removeLocation(data);
    } catch (Exception e) {
      return e.getMessage();
    }
  }
}

